241.   private pollGamepads(timestamp: number): void {
242.     const pads = navigator.getGamepads();
243.     this.gamepadConnected = pads.some(Boolean);
244.     const connectedIndices = new Set<number>();
245.     for (const pad of pads) {
246.       if (!pad || pad.mapping !== "standard") continue;
247.       connectedIndices.add(pad.index);
248.       const previous = this.gamepadSnapshots.get(pad.index) ?? {
249.         buttons: [],
250.         axes: [],
251.       };
252.       const next: GamepadSnapshot = {
253.         buttons: pad.buttons.map((button) => button.pressed),
254.         axes: pad.axes.map((axis) => normalizeAnalogAxis(axis)),
255.       };
256.       for (const binding of STANDARD_GAMEPAD_BINDINGS) {
257.         this.updateGamepadBinding(pad.index, binding, previous, next, timestamp);
258.       }
259.       this.updateGamepadCursor(pad);
260.       if (
261.         this.cursorActive
262.         && next.buttons[11] === true
263.         && previous.buttons[11] !== true
264.       ) {
265.         this.clickCursor();
266.         inputSource.set("gamepad");
267.         this.updatePresentation("gamepad");
268.       }
269.       this.gamepadSnapshots.set(pad.index, next);
270.     }
271.     for (const index of this.gamepadSnapshots.keys()) {
272.       if (connectedIndices.has(index)) continue;
273.       this.gamepadSnapshots.delete(index);
274.       const released = this.state.releaseMatching(`gamepad:${index}:`);
275.       for (const entry of released) this.releaseSyntheticToken(entry.token);
276.     }
277.   }
278. 
279.   private updateGamepadBinding(
280.     index: number,
281.     binding: StandardGamepadBinding,
282.     previous: GamepadSnapshot,
283.     next: GamepadSnapshot,
284.     timestamp: number,
285.   ): void {
286.     const token = binding.button !== undefined
287.       ? `gamepad:${index}:button:${binding.button}`
288.       : `gamepad:${index}:axis:${binding.axis}:${binding.direction}`;
289.     const wasPressed = binding.button !== undefined
290.       ? previous.buttons[binding.button] === true
291.       : this.axisPressed(
292.         previous.axes[binding.axis ?? 0] ?? 0,
293.         binding.direction ?? 1,
294.       );
295.     const pressed = binding.button !== undefined
296.       ? next.buttons[binding.button] === true
297.       : this.axisPressed(
298.         next.axes[binding.axis ?? 0] ?? 0,
299.         binding.direction ?? 1,
300.       );
301.     if (pressed && !wasPressed) {
302.       const action = resolveGamepadAction(binding, this.getContext());
303.       if (
304.         this.cursorActive
305.         && (
306.           action.startsWith("navigate")
307.           || action.startsWith("move")
308.         )
309.       ) {
310.         this.cursorActive = false;
311.         this.updateCursor();
312.       }
313.       const event = this.state.press(token, action, "gamepad", timestamp);
314.       if (event) {
315.         this.dispatch(event);
316.       } else {
317.         const descriptor = this.keyForAction(this.contextualizeAction(action));
318.         if (descriptor) {
319.           this.pressSyntheticToken(token, descriptor, false, false);
320.         }
321.       }
322.     } else if (!pressed && wasPressed) {
323.       this.state.release(token);
324.       this.releaseSyntheticToken(token);
325.     }
326.   }
327. 
328.   private axisPressed(value: number, direction: -1 | 1): boolean {
329.     return direction < 0 ? value <= -0.55 : value >= 0.55;
330.   }
331. 
332.   private updateGamepadCursor(gamepad: Gamepad): void {
333.     const x = normalizeAnalogAxis(gamepad.axes[2] ?? 0);
334.     const y = normalizeAnalogAxis(gamepad.axes[3] ?? 0);
335.     if (x === 0 && y === 0) return;
336.     const bounds = this.game.canvas.getBoundingClientRect();
337.     if (!this.cursorActive) {
338.       this.cursorX = bounds.left + bounds.width / 2;
339.       this.cursorY = bounds.top + bounds.height / 2;
340.     }
341.     const speed = 12;
342.     this.cursorX = Math.max(
343.       bounds.left,
344.       Math.min(bounds.right, this.cursorX + x * speed),
345.     );
346.     this.cursorY = Math.max(
347.       bounds.top,
348.       Math.min(bounds.bottom, this.cursorY + y * speed),
349.     );
350.     this.cursorActive = true;
351.     inputSource.set("gamepad");
352.     this.updatePresentation("gamepad");
353.     this.updateCursor();
354.     const mouseMove = new MouseEvent("mousemove", {
355.       bubbles: true,
356.       clientX: this.cursorX,
357.       clientY: this.cursorY,
358.     });
359.     this.syntheticEvents.add(mouseMove);
360.     this.game.canvas.dispatchEvent(mouseMove);
361.   }
362. 
363.   private dispatch(event: SemanticInputEvent): void {
364.     inputSource.set(event.source);
365.     this.updatePresentation(event.source);
366.     const action = this.contextualizeAction(event.action);
367.     if (this.handleMobileTextInput(action)) return;
368.     if (action === "battleLogUp" || action === "battleLogDown") {
369.       this.dispatchWheel(action === "battleLogUp" ? -120 : 120);
370.       return;
371.     }
372.     const descriptor = event.token && event.repeated
373.       ? this.heldSyntheticKeys.get(event.token)
374.       : this.keyForAction(action);
375.     if (!descriptor) return;
376.     if (event.token) {
377.       this.pressSyntheticToken(event.token, descriptor, event.repeated);
378.     } else {
379.       this.dispatchKey("keydown", descriptor, event.repeated);
380.       window.setTimeout(() => this.dispatchKey("keyup", descriptor, false), 0);
381.     }
382.   }
383. 
384.   private pressSyntheticToken(
385.     token: string,
386.     descriptor: KeyDescriptor,
387.     repeated: boolean,
388.     dispatchInitial = true,
389.   ): void {
390.     const existing = this.heldSyntheticKeys.get(token);
391.     if (repeated && existing) {
392.       this.dispatchKey("keydown", existing, true);
393.       return;
394.     }
395.     if (existing) return;
396.     this.heldSyntheticKeys.set(token, descriptor);
397.     const firstOwner = this.syntheticKeyOwnership.acquire(
398.       token,
399.       descriptor.code,
400.     );
401.     if (dispatchInitial && firstOwner) {
402.       this.dispatchKey("keydown", descriptor, false);
403.     }
404.   }
405. 
406.   private releaseSyntheticToken(token: string): void {
407.     const descriptor = this.heldSyntheticKeys.get(token);
408.     if (!descriptor) return;
409.     this.heldSyntheticKeys.delete(token);
410.     const release = this.syntheticKeyOwnership.release(token);
411.     if (release?.finalOwner) {
412.       this.dispatchKey("keyup", descriptor, false);
413.     }
414.   }
415. 
416.   private contextualizeAction(action: InputAction): InputAction {
417.     const context = this.getContext();
418.     if (context === "exploration" && action.startsWith("navigate")) {
419.       return action.replace("navigate", "move") as InputAction;
420.     }
421.     if (context === "cutscene" || context === "ending") {
422.       if (action === "confirm" || action === "interact") return "cutsceneAdvance";
423.       if (action === "cancel") return "cutsceneSkip";
424.     }
425.     if (context === "inventory") {
426.       const inventoryActions: Partial<Record<InputAction, InputAction>> = {
427.         navigateUp: "inventoryPrevious",
428.         navigateDown: "inventoryNext",
429.         navigateLeft: "inventoryPagePrevious",
430.         navigateRight: "inventoryPageNext",
431.         confirm: "inventoryPrimary",
432.       };
433.       return inventoryActions[action] ?? action;
434.     }
435.     if (context === "codex") {
436.       if (action === "interact") return "codexSearch";
437.       if (action === "battleTargetPrevious") return "codexCategoryPrevious";
438.       if (action === "battleTargetNext") return "codexCategoryNext";
439.     }
440.     return action;
441.   }
442. 
443.   private keyForAction(action: InputAction): KeyDescriptor | undefined {
444.     if (
445.       (
446.         this.getContext() === "shop"
447.         || this.getContext() === "chronicle"
448.       )
449.       && action.startsWith("navigate")
450.     ) {
451.       const direction = action.slice("navigate".length);
452.       return { code: `Arrow${direction}`, key: `Arrow${direction}` };
453.     }
454.     if (
455.       this.getContext() === "characterCreation"
