   private updateGamepadCursor(gamepad: Gamepad): void {
     const x = normalizeAnalogAxis(gamepad.axes[2] ?? 0);
     const y = normalizeAnalogAxis(gamepad.axes[3] ?? 0);
     if (x === 0 && y === 0) return;
     const bounds = this.game.canvas.getBoundingClientRect();
