node --input-type=module - <<'NODE'
import { chromium } from 'playwright';
const browser = await chromium.connectOverCDP('http://127.0.0.1:9222');
const pages = browser.contexts().flatMap((context) => context.pages());
const page = pages.find((candidate) => candidate.url().endsWith('/game.html'));
if (!page) throw new Error('Android game tab not found');
const state = await page.evaluate(() => ({
  readyState: document.readyState,
  debugState: document.querySelector('#debug-state')?.textContent,
  canvas: (() => {
    const canvas = document.querySelector('#game-container canvas');
    if (!(canvas instanceof HTMLCanvasElement)) return null;
    const rect = canvas.getBoundingClientRect();
    return { width: canvas.width, height: canvas.height, rect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height }, inputSource: canvas.dataset.inputSource };
  })(),
  touchButtons: [...document.querySelectorAll('.touch-control')].map((button) => ({ action: button.getAttribute('data-action'), hidden: button.hasAttribute('hidden'), rect: button.getBoundingClientRect().toJSON() })),
}));
console.log(JSON.stringify(state, null, 2));
await browser.close();
