import { chromium } from 'playwright';
const browser = await chromium.launch({ headless: true });
for (const mode of ['click', 'tap']) {
  const context = await browser.newContext({ viewport: { width: 320, height: 749 }, isMobile: true, hasTouch: true });
  const page = await context.newPage();
  await page.goto('http://127.0.0.1:4173/game.html', { waitUntil: 'networkidle' });
  await page.waitForFunction(() => document.querySelector('#debug-state')?.textContent?.includes('BOOT | Screen: title'));
  const button = page.locator('[data-action="confirm"]');
  if (mode === 'click') await button.click(); else await button.tap();
  await page.waitForTimeout(100);
  console.log(mode, await page.locator('#debug-state').textContent());
  await context.close();
}
await browser.close();
