1. import * as Phaser from "phaser";
2. import { isLocalDev } from "../config";
3. import {
4.   auditLayout,
5.   layoutVerticalStack,
6.   type LayoutAuditItem,
7.   type LayoutAuditResult,
8.   type LayoutRect,
9. } from "../systems/layout";
10. 
11. interface LayoutGroup {
12.   id: string;
13.   container: Phaser.GameObjects.Container;
14.   viewport?: LayoutRect;
15. }
16. 
17. const sceneGroups = new WeakMap<Phaser.Scene, Map<string, LayoutGroup>>();
18. const installedScenes = new WeakSet<Phaser.Scene>();
19. 
20. function getReportElement(): HTMLElement | null {
21.   return typeof document === "undefined"
22.     ? null
23.     : document.getElementById("layout-report");
24. }
25. 
26. function isVisibleObject(
27.   object: Phaser.GameObjects.GameObject,
28. ): object is Phaser.GameObjects.Text {
29.   return object instanceof Phaser.GameObjects.Text
30.     && object.visible
31.     && object.active
32.     && object.alpha > 0
33.     && object.text.trim().length > 0
34.     && object.getData("layoutAuditIgnore") !== true;
35. }
36. 
37. function getObjectId(
38.   groupId: string,
39.   object: Phaser.GameObjects.Text,
40.   index: number,
41. ): string {
42.   const explicit = object.getData("layoutId");
43.   if (typeof explicit === "string" && explicit.length > 0) return explicit;
44.   const text = object.text.replace(/\s+/g, " ").trim().slice(0, 32);
45.   return `${groupId}:text-${index}:${text}`;
46. }
47. 
48. export function getScaledBounds(
49.   object: Phaser.GameObjects.Components.GetBounds,
50. ): LayoutRect {
51.   const bounds = object.getBounds();
52.   return {
53.     x: bounds.x,
54.     y: bounds.y,
55.     width: bounds.width,
56.     height: bounds.height,
57.   };
58. }
59. 
60. export function syncInteractiveHitArea(
61.   object: Phaser.GameObjects.Text,
62.   padding = 0,
63. ): void {
64.   if (!object.input?.enabled) return;
65.   const width = object.width + padding * 2;
66.   const height = object.height + padding * 2;
67.   object.input.hitArea = new Phaser.Geom.Rectangle(
68.     -padding,
69.     -padding,
70.     width,
71.     height,
72.   );
73.   object.input.hitAreaCallback = Phaser.Geom.Rectangle.Contains;
74. }
75. 
76. export function layoutTextStack(
77.   objects: readonly Phaser.GameObjects.Text[],
78.   options: {
79.     x: number;
80.     y: number;
81.     width?: number;
82.     gap?: number;
83.     align?: "start" | "center" | "end";
84.     hitAreaPadding?: number;
85.   },
86. ): number {
87.   const layout = layoutVerticalStack(
88.     objects.map((object, index) => ({
89.       id: String(index),
90.       width: object.displayWidth,
91.       height: object.displayHeight,
92.     })),
93.     options,
94.   );
95.   layout.items.forEach((item, index) => {
96.     const object = objects[index];
97.     const bounds = object.getBounds();
98.     object.setPosition(
99.       object.x + item.x - bounds.x,
100.       object.y + item.y - bounds.y,
101.     );
102.     syncInteractiveHitArea(object, options.hitAreaPadding ?? 0);
103.   });
104.   return layout.height;
105. }
106. 
107. export function registerLayoutGroup(
108.   scene: Phaser.Scene,
109.   id: string,
110.   container: Phaser.GameObjects.Container,
111.   viewport?: LayoutRect,
112. ): void {
113.   let groups = sceneGroups.get(scene);
114.   if (!groups) {
115.     groups = new Map<string, LayoutGroup>();
116.     sceneGroups.set(scene, groups);
117.   }
118.   container.setData("layoutGroupId", id);
119.   groups.set(id, { id, container, viewport });
120.   container.once(Phaser.GameObjects.Events.DESTROY, () => {
121.     groups?.delete(id);
122.   });
123. }
124. 
125. export function updateLayoutGroupViewport(
126.   scene: Phaser.Scene,
127.   id: string,
128.   viewport: LayoutRect,
129. ): void {
130.   const group = sceneGroups.get(scene)?.get(id);
131.   if (group) group.viewport = viewport;
132. }
133. 
134. function collectGroupItems(group: LayoutGroup): LayoutAuditItem[] {
135.   return group.container.list
136.     .filter(isVisibleObject)
137.     .map((object, index) => ({
138.       id: getObjectId(group.id, object, index),
139.       bounds: getScaledBounds(object),
140.       allowOverlapWith: object.getData("layoutAllowOverlapWith") as
141.         | readonly string[]
142.         | undefined,
143.     }));
144. }
145. 
146. export function auditSceneLayout(scene: Phaser.Scene): {
147.   scene: string;
148.   groups: Record<string, LayoutAuditResult & { items: LayoutAuditItem[] }>;
149.   overlapCount: number;
150.   clippingCount: number;
151. } {
152.   const groups = sceneGroups.get(scene);
153.   const results: Record<
154.     string,
155.     LayoutAuditResult & { items: LayoutAuditItem[] }
156.   > = {};
157.   let overlapCount = 0;
158.   let clippingCount = 0;
159.   groups?.forEach((group) => {
160.     const items = collectGroupItems(group);
161.     const result = auditLayout(items, group.viewport);
162.     results[group.id] = { ...result, items };
163.     overlapCount += result.overlaps.length;
164.     clippingCount += result.clipping.length;
165.   });
166.   return {
167.     scene: scene.scene.key,
168.     groups: results,
169.     overlapCount,
170.     clippingCount,
171.   };
172. }
173. 
174. function publishLayoutReport(scene: Phaser.Scene): void {
175.   const report = auditSceneLayout(scene);
176.   scene.game.canvas.dataset.layoutOverlapCount = String(report.overlapCount);
177.   scene.game.canvas.dataset.layoutClippingCount = String(report.clippingCount);
178.   scene.game.canvas.dataset.layoutScene = report.scene;
179.   const element = getReportElement();
180.   if (element) element.textContent = JSON.stringify(report);
181. }
182. 
183. export function installSceneLayoutAudit(scene: Phaser.Scene): void {
184.   if (!isLocalDev() || installedScenes.has(scene)) return;
185.   installedScenes.add(scene);
186.   let lastAudit = 0;
187.   const audit = (time: number): void => {
188.     if (time - lastAudit < 200) return;
189.     lastAudit = time;
190.     publishLayoutReport(scene);
191.   };
192.   scene.events.on("postupdate", audit);
193.   scene.events.once("shutdown", () => {
194.     scene.events.off("postupdate", audit);
195.     sceneGroups.delete(scene);
196.     installedScenes.delete(scene);
197.   });
198.   publishLayoutReport(scene);
199. }
