     const height = finiteNonNegative(itemHeights[index]);
     const itemEnd = cursor + height;
     if (start === itemHeights.length && itemEnd > safeOffset) start = index;
     if (cursor < safeOffset + safeHeight) end = index + 1;
     cursor = itemEnd + safeGap;

